item.command:
/bin/bash -lc "python3 - <<'PY'
import urllib.request
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/'
for f in ['Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarloMultiGPU.cpp','Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarlo_kernel.cu','Samples/5_Domain_Specific/MonteCarloMultiGPU/CMakeLists.txt']:
 print('\\nSOURCE',f)
 try:
  s=urllib.request.urlopen(base+f,timeout=20).read().decode()
  for i,line in enumerate(s.splitlines(),1):
   if f.endswith('CMakeLists.txt') or any(x in line for x in ['sumReserve','nOptions =','PATH_N','srand','randFloat','malloc','cudaMalloc','curand_init','Total time','MAX_OPTIONS','THREAD_N']): print(i,line)
 except Exception as e: print(type(e).__name__,str(e))
PY"

